  string folder;WuxiaGame game;int errors;float minFps=999;int samples;double totalFrame;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
  static void Boot(){foreach(var arg in Environment.GetCommandLineArgs())if(arg.StartsWith("--wuxia-capture=")){var game=FindFirstObjectByType<WuxiaGame>();var capture=game.gameObject.AddComponent<PreviewCapture>();capture.folder=arg.Substring("--wuxia-capture=".Length);}}
  IEnumerator Start(){if(string.IsNullOrEmpty(folder))yield break;Directory.CreateDirectory(folder);game=GetComponent<WuxiaGame>();game.skipSimulation=true;Application.logMessageReceived+=Log;Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(1);if(Array.IndexOf(Environment.GetCommandLineArgs(),"--wuxia-endless-only")>=0){yield return EndlessChecks();Application.logMessageReceived-=Log;File.WriteAllText(Path.Combine(folder,"player-validation.txt"),$"Unity {Application.unityVersion}\nCurrent endless expansion native rendering and UGUI: completed\nRuntime errors: {errors}\nFrames: {samples}\n");Application.Quit(errors==0?0:1);yield break;}yield return Save("01-menu");game.ShowStory();yield return Save("02-story");game.StartStory();yield return Save("03-guide");game.FinishGuide();for(int i=0;i<100;i++){game.Step(1/60f,new InputFrame{move=1,jump=i==30,jumpHeld=true});yield return null;}yield return Save("04-story-play");game.StartTraining();game.FinishGuide();game.player.Place(550,620);game.invincibleUntil=10000;for(int i=0;i<90;i++){game.Step(1/60f,default);yield return null;}yield return Save("04b-enemies");game.StartFinal();game.FinishGuide();game.player.Place(420,620);game.invincibleUntil=10000;for(int i=0;i<180;i++){game.Step(1/60f,default);yield return null;}game.Step(1/60f,new InputFrame{ward=true});for(int i=0;i<20;i++){game.Step(1/60f,default);yield return null;}yield return Save("05-formation");for(int i=0;i<8;i++)game.Step(1/60f,default);yield return Save("05b-formation-release");for(int i=0;i<32;i++)game.Step(1/60f,default);yield return Save("05c-formation-hit");game.ChangeBoss("novaTell",3);for(int i=0;i<155;i++){game.Step(1/60f,default);yield return null;}yield return Save("06-master-warning");for(int i=0;i<40;i++){game.Step(1/60f,default);yield return null;}yield return Save("07-master-surge");game.StartEndless();game.FinishGuide();foreach(var e in game.enemies)e.hp=0;game.FinishWave();for(int i=0;i<275;i++){game.Step(1/60f,new InputFrame{move=1});yield return null;}yield return null;Canvas.ForceUpdateCanvases();yield return Save("08a-cards-unselected");float beforeHp=game.hp,beforeMax=game.MaxHP;Click("机缘 · "+game.offers[0]);Click("机缘 · "+game.offers[1]);Click("机缘 · heal");Verify(game.pendingUpgrade=="heal"&&game.hp==beforeHp&&game.MaxHP==beforeMax,"鼠标射线命中卡面、改选三次且未提前生效");yield return Save("08-cards");Click("确认 · 进入下一步");Verify(game.phase==GamePhase.Play,"原生确认按钮触发回春丹并开始下一波");game.run.wave=4;game.BeginWave();game.boss.dir=-1;game.boss.Place(1000,620);game.ChangeBoss("charge",3);game.boss.targetX=450;for(int i=0;i<75;i++){game.Step(1/60f,default);yield return null;}yield return Save("09-stone-platforms");game.run.wave=4;game.BeginWave();game.player.Place(770,620);game.boss.Place(1000,620);game.ChangeBoss("slamTell",.05f);for(int i=0;i<28;i++){game.Step(1/60f,default);yield return null;}yield return Save("09b-ground-quake");game.StartEndless();game.FinishGuide();yield return Save("09c-symmetric-platforms");foreach(var upgrade in game.data.upgrades)if(upgrade.id!="heal")game.hp=Rules.Apply(game.data,game.run,upgrade.id,game.hp);game.ui.Refresh();yield return Save("09d-compact-talents");yield return AnimationChecks();yield return EndlessChecks();game.ShowMenu();yield return Save("10-return-menu");game.StartEndless();game.FinishGuide();game.invincibleUntil=10000;game.skipSimulation=false;game.automatedPlayback=true;var liveFrames=new List<float>();for(int i=0;i<240;i++){game.playbackInput=new InputFrame{move=i/40%2==0?1:-1,attack=i%50>30,jump=i==50||i==130,jumpHeld=true,ward=i==75,ranged=i==185};yield return null;if(i>30)liveFrames.Add(Time.unscaledDeltaTime*1000);}game.playbackInput=default;yield return Save("11-live-physics-render");game.ShowMenu();yield return null;game.StartTraining();game.FinishGuide();yield return null;game.ShowMenu();yield return null;liveFrames.Sort();File.WriteAllText(Path.Combine(folder,"live-run-validation.txt"),$@"Actual Update + FixedUpdate + LateUpdate, 240 frames
