");game.automatedPlayback=false;game.skipSimulation=true;Application.logMessageReceived-=Log;File.WriteAllText(Path.Combine(folder,"player-validation.txt"),$"Unity {Application.unityVersion}\nNative player rendering and UGUI: completed\nRuntime errors: {errors}\nFrames: {samples}\nAverage frame time (scripted capture): {(samples>0?totalFrame/samples*1000:0):0.00} ms\n");Application.Quit(errors==0?0:1);}
  IEnumerator EndlessChecks(){
   game.StartEndless();game.FinishGuide();game.run.wave=11;game.BeginWave();game.invincibleUntil=10000;game.player.Place(170,620);game.Step(1/60f,default);game.player.Place(1500,620);for(int i=0;i<24;i++)game.Step(1/60f,default);Verify(game.WuxiaPortalsActive,"原生画面使用阴阳八卦、墨烟与朱砂符，没有石拱门贴图");yield return Save("18-demon-portals");for(int i=0;i<65;i++)game.Step(1/60f,default);Verify(game.enemies.Exists(e=>e.kind=="bone")&&game.enemies.Exists(e=>e.kind=="cultist")&&game.enemies.Exists(e=>e.kind=="eye"),"实际播放器从魔门生成三种新敌人");yield return Save("19-new-enemies");for(int i=0;i<60;i++)game.Step(1/60f,default);yield return Save("19b-enemy-attacks");Verify(game.Targets().Count==14&&game.ReinforcementBatch==1,"第十二波首批在实际播放器中完整生成十四名敌人");int batch=game.ReinforcementBatch;for(int i=0;i<900;i++)game.Step(1/60f,default);Verify(game.ReinforcementBatch==batch,"实际播放器等待十五秒，未清空敌人不会开启下批");foreach(var e in game.enemies){e.hp=0;e.Disable();}for(int i=0;i<230;i++)game.Step(1/60f,new InputFrame{move=i<30?-1:0});Verify(game.ReinforcementBatch==2&&game.Targets().Count==14&&game.phase==GamePhase.Play,"实际播放器清完后生成第二批完整十四只，无提前选卡");yield return Save("19c-second-full-pack");
   game.StartEndless();game.FinishGuide();game.run.wave=98;game.BeginWave();game.invincibleUntil=10000;for(int i=0;i<150;i++)game.Step(1/60f,default);Verify(game.ReleasedEnemies==18&&game.ReinforcementBatch==1&&game.ReinforcementBatches==12,"第九十九波十二小批，首批先释放十八只控制同屏量");yield return Save("19d-growing-wave99");foreach(var e in game.enemies){e.hp=0;e.Disable();}game.Step(1/60f,default);Verify(game.ReleasedEnemies==35&&game.ReinforcementBatch==1&&game.Targets().Count==17,"同一小批继续补齐三十五只，未被十八只性能上限截断");yield return Save("19e-same-pack-replenish");foreach(var e in game.enemies){e.hp=0;e.Disable();}for(int i=0;i<260;i++)game.Step(1/60f,default);bool strengthened=game.ReinforcementBatch==2;foreach(var e in game.enemies)if(e.hp>0)strengthened&=e.attackPower>Rules.Wave(99).damage;Verify(strengthened,"实际播放器第二小批继续提高敌人攻击数值");yield return Save("19f-stronger-second-pack");
   game.ShowCards();game.offers=new[]{"rain","finger","brand"};game.ui.ShowCards();yield return Save("20-skill-cards");float hp=game.hp;Click("机缘 · rain");Click("机缘 · finger");Click("机缘 · brand");Verify(game.run.Level("rain")==0&&game.run.Level("finger")==0&&game.run.Level("brand")==0&&game.hp==hp,"新技能卡鼠标反复改选不提前生效");Click("确认 · 进入下一步");Verify(game.run.Level("brand")==1&&game.run.Level("rain")==0&&game.phase==GamePhase.Play,"确认新技能后仅学习选中的焚邪剑印");
   game.ShowCards();game.offers=new[]{"swift","armor","focus"};game.ui.ShowCards();yield return Save("21-attribute-cards");
   game.StartFinal();game.FinishGuide();game.player.Place(500,620);game.invincibleUntil=10000;game.boss.hp=game.boss.maxHp=1000;game.ChangeBoss("recover",100);game.run=new RogueState();game.run.levels["rain"]=2;game.run.nextRain=0;for(int i=0;i<12;i++)game.Step(1/60f,default);yield return Save("22-sword-rain");for(int i=0;i<60;i++)game.Step(1/60f,default);
   game.run.levels.Clear();game.run.levels["finger"]=2;game.run.nextFinger=0;for(int i=0;i<12;i++)game.Step(1/60f,default);yield return Save("23-sword-finger");for(int i=0;i<50;i++)game.Step(1/60f,default);
   game.run.levels.Clear();game.run.levels["brand"]=2;game.run.nextBrand=0;for(int i=0;i<25;i++)game.Step(1/60f,default);yield return Save("24-sword-brand-tell");for(int i=0;i<26;i++)game.Step(1/60f,default);yield return Save("24b-sword-brand-burst");
   game.run.levels.Clear();game.run.levels["afterimage"]=2;game.player.Place(game.boss.X-145,620);game.Step(1/60f,new InputFrame{dash=true,move=1});for(int i=0;i<16;i++)game.Step(1/60f,default);yield return Save("25-dash-afterimage");
   game.StartEndless();game.FinishGuide();game.run.wave=22;game.BeginWave();game.invincibleUntil=10000;foreach(var u in game.data.upgrades)if(u.id!="heal")game.hp=Rules.Apply(game.data,game.run,u.id,game.hp);game.skipSimulation=false;game.automatedPlayback=true;var frames=new List<float>();int peak=0;
   for(int i=0;i<660;i++){game.playbackInput=new InputFrame{move=i/90%2==0?1:-1,jump=i%80==0,jumpHeld=true,attack=i%25<12,ranged=i%180==0,ward=i%210==0,dash=i%130==0};yield return null;if(i>30)frames.Add(Time.unscaledDeltaTime*1000);int alive=0;foreach(var e in game.enemies)if(e.hp>0)alive++;peak=Math.Max(peak,alive);}
   game.playbackInput=default;yield return Save("26-live-endless");game.skipSimulation=true;game.automatedPlayback=false;frames.Sort();File.WriteAllText(Path.Combine(folder,"endless-live-validation.txt"),$"Actual Update + FixedUpdate + LateUpdate, 660 frames\nWave 23, all 19 non-heal talents learned, clear-then-next reinforcement batches\nPeak living enemies: {peak}\nP50 frame ms: {frames[frames.Count/2]:0.00}\nP95 frame ms: {frames[Mathf.FloorToInt(frames.Count*.95f)]:0.00}\nRuntime errors so far: {errors}\n");Verify(game.PortalCount<=2&&peak<=WuxiaGame.MaxBatchEnemies,"实际连续无尽战斗保持敌人与魔门数量上限");game.ShowMenu();Verify(game.PendingEnemies==0&&game.PortalCount==0&&game.SwordBrandCount==0,"实际原生无尽战斗返回主页完整清理");
  }
  IEnumerator AnimationChecks(){
   game.StartTraining();game.FinishGuide();game.invincibleUntil=10000;game.boss.hp=0;game.boss.Disable();foreach(var e in game.enemies){e.hp=0;e.Disable();}game.invincibleUntil=-1;game.player.Place(400,620);for(int i=0;i<8;i++)game.Step(1/60f,default);game.facing=1;game.RenderActors();yield return Save("12-waist-right");game.facing=-1;game.RenderActors();yield return Save("12b-waist-left");game.facing=1;for(int i=0;i<8;i++){for(int j=0;j<6;j++)game.Step(1/60f,new InputFrame{move=1});yield return Save("13-run-"+i);}
   game.player.Place(500,620);for(int i=0;i<8;i++)game.Step(1/60f,default);game.Step(1/60f,new InputFrame{dash=true,move=1});yield return Save("13b-dash-start");for(int i=0;i<16;i++)game.Step(1/60f,default);yield return Save("13c-dash-end");
   game.StartStory();game.FinishGuide();foreach(var e in game.enemies){e.hp=0;e.Disable();}var ledge=game.platforms.Find(p=>p.data.y<620);game.player.Place(ledge.data.x+ledge.data.w*.5f,ledge.data.y+ledge.data.h+game.player.TerrainHeight+2);game.player.VY=-740;Physics2D.SyncTransforms();for(int i=0;i<2;i++)game.Step(1/60f,new InputFrame{jumpHeld=true});Verify(game.player.Feet-game.player.TerrainHeight>=ledge.data.y+ledge.data.h-1.5f,"原生剧情跳跃头部不会进入高台");yield return Save("13d-head-under-platform");
   game.StartTraining();game.FinishGuide();game.boss.hp=0;game.boss.Disable();foreach(var e in game.enemies){e.hp=0;e.Disable();}
   game.player.Place(500,620);for(int i=0;i<6;i++)game.Step(1/60f,default);for(int i=0;i<9;i++)game.Step(1/60f,new InputFrame{jump=i==0,jumpHeld=true,attack=true});yield return Save("14-jump-slash");
   foreach(int dir in new[]{-1,1}){game.StartTraining();game.FinishGuide();game.invincibleUntil=10000;game.player.Place(780,620);game.boss.Place(1000,620);game.boss.active=true;game.boss.dir=dir;game.boss.targetX=1000+dir*220;game.ChangeBoss("charge",2);for(int i=0;i<12;i++)game.Step(1/60f,default);Verify(game.boss.view.renderer.flipX==(dir>0)&&Mathf.Sign(game.boss.VX)==dir,"石像面朝行进方向 "+dir);yield return Save("15-charge-"+(dir<0?"left":"right"));}
   game.StartEndless();game.FinishGuide();game.invincibleUntil=10000;game.player.Place(580,620);foreach(var e in game.enemies)e.hp=e.maxHp=100;game.hp=Rules.Apply(game.data,game.run,"frost",game.hp);game.run.nextFrost=game.clock+.05f;for(int i=0;i<12;i++)game.Step(1/60f,default);yield return Save("16-frost-crystals");
   game.StartFinal();game.FinishGuide();game.invincibleUntil=10000;game.player.Place(500,620);game.boss.active=true;game.ChangeBoss("recover",100);for(int i=0;i<43;i++)game.Step(1/60f,new InputFrame{ranged=i==0});Verify(game.boss.hp<game.boss.maxHp,"实际飞剑命中首领并扣血");yield return Save("17-flying-sword-impact");
  }
  IEnumerator Save(string name){if(game.player!=null)File.AppendAllText(Path.Combine(folder,"positions.txt"),name+" player="+game.player.X+","+game.player.Feet+" camera="+game.gameCamera.transform.position+" boss="+(game.boss!=null?game.boss.X+","+game.boss.Feet+" view="+game.boss.view.root.transform.position+" scale="+game.boss.view.root.transform.localScale:"none")+"\n");game.ui.FitScreen();game.ui.Refresh();yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
  void Verify(bool ok,string description){File.AppendAllText(Path.Combine(folder,"pointer-validation.txt"),(ok?"PASS: ":"FAIL: ")+description+"\n");if(!ok){Debug.LogError(description);Application.Quit(1);}}
  void Click(string name){var button=Array.Find(game.ui.GetComponentsInChildren<Button>(true),b=>b.name==name&&b.gameObject.activeInHierarchy);if(!button){Verify(false,"找不到按钮 "+name);return;}var corners=new Vector3[4];button.GetComponent<RectTransform>().GetWorldCorners(corners);var pointer=new PointerEventData(EventSystem.current){position=(corners[0]+corners[2])*.5f,button=PointerEventData.InputButton.Left};var results=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,results);if(results.Count==0){Verify(false,"鼠标射线未命中 "+name);return;}ExecuteEvents.ExecuteHierarchy(results[0].gameObject,pointer,ExecuteEvents.pointerClickHandler);}
  void Update(){if(folder==null)return;if(Time.unscaledDeltaTime>0){samples++;totalFrame+=Time.unscaledDeltaTime;minFps=Mathf.Min(minFps,1/Time.unscaledDeltaTime);}}
  void Log(string condition,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)errors++;}
 }
